INSERT INTO `governorate` VALUES (1,'جنين','Jenin','Northernmost governorate of the West Bank, known for its agriculture and the Marj Ibn Amer plain.'),(2,'طوباس','Tubas','Northeastern West Bank governorate in the Jordan Valley, mainly agricultural.'),(3,'طولكرم','Tulkarm','Northwestern West Bank governorate, known for farming and light industry.'),(4,'نابلس','Nablus','Largest governorate in the northern West Bank and a major commercial and cultural center, known for olive oil soap and kunafa.'),(5,'قلقيلية','Qalqilya','Western West Bank governorate, known for fertile land and agricultural production.'),(6,'سلفيت','Salfit','Central West Bank governorate, known for olive groves and olive oil production.'),(7,'رام الله والبيرة','Ramallah and Al-Bireh','Central West Bank governorate and the administrative and political center of the Palestinian Authority.'),(8,'أريحا والأغوار','Jericho and Al-Aghwar','Located in the Jordan Valley, one of the oldest continuously inhabited cities in the world and the lowest city on Earth.'),(9,'القدس','Jerusalem','Holy city of religious significance to Islam, Christianity, and Judaism, and the capital of the State of Palestine.'),(10,'بيت لحم','Bethlehem','Southern West Bank governorate, the birthplace of Jesus Christ and home to the Church of the Nativity.'),(11,'الخليل','Hebron','Largest governorate in the West Bank by population and area, known for glass, pottery, and grape production.'),(12,'شمال غزة','North Gaza','Northernmost governorate of the Gaza Strip, including Jabalia and Beit Hanoun.'),(13,'غزة','Gaza','Central governorate of the Gaza Strip, containing Gaza City, the largest city in the Strip.'),(14,'دير البلح','Deir al-Balah','Central Gaza Strip governorate, known for its palm groves.'),(15,'خان يونس','Khan Yunis','Southern Gaza Strip governorate with a historic Mamluk-era fortress.'),(16,'رفح','Rafah','Southernmost governorate of the Gaza Strip, bordering Egypt.'),(17,'جنين','jenin',NULL);
